add('table', caption='TABLE XII. TRAINED FORECASTERS VS THE BEST TUNED FIXED SCHEDULE: PAIRED DIFFERENCE IN J (POSITIVE = FORECASTER WORSE); HOLM-ADJUSTED p OVER 72 COMPARISONS', header=['Policy', 'ΔJ per generated unit ± 95% CI', 't p', 'Wilcoxon p'], widths=[.30, .34, .18, .18], fs=8, rows=rows)
